CSS Starter:
body { font: 17px/1.5 'Inter Tight', sans-serif; color: #111418; background: #fff; }
main { max-width: 62ch; margin-inline: 8vw; }
h1 { font-size: clamp(2.5rem, 7vw, 6rem); font-weight: 600; line-height: 1; }

.scene { height: 80vh; background: #0e1116; }
.scene canvas { width: 100%; height: 100%; display: block; }
@media (prefers-reduced-motion: reduce) { .scene canvas { display: none; } .scene { background: url(poster.webp) center / cover; } }

.band { padding-block: 96px; background: #2446d8; color: #fff; }
.band--yellow { background: #ffc72c; color: #14161a; }
.band h2 { font-size: clamp(2rem, 5vw, 4rem); }

:root { color-scheme: dark; }
body { background: #0b0d10; color: #e8eaed; line-height: 1.6; }
.card { background: #161a20; border: 1px solid #262b33; }

a:focus-visible, button:focus-visible, input:focus-visible { outline: 3px solid #0b57d0; outline-offset: 2px; }
button, input { min-height: 44px; font: inherit; }
body { font: 18px/1.6 'Atkinson Hyperlegible', sans-serif; }

.reveal { opacity: 0; transform: translateY(24px); transition: opacity 600ms cubic-bezier(0.22, 1, 0.36, 1), transform 600ms cubic-bezier(0.22, 1, 0.36, 1); }
.reveal.in { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) { .reveal { opacity: 1; transform: none; transition: none; } }

.btn { transition: transform 100ms ease-out, background-color 150ms ease-out; }
.btn:active { transform: scale(0.97); }
@media (prefers-reduced-motion: reduce) { .btn { transition: none; } .btn:active { transform: none; } }

body { font: 1.125rem/1.6 Lexend, sans-serif; max-width: 60ch; }
label { display: block; margin-bottom: 6px; font-weight: 600; }
input, button { min-height: 48px; }

table { border-collapse: collapse; font: 13px/1.3 'IBM Plex Sans', sans-serif; font-variant-numeric: tabular-nums; }
th { position: sticky; top: 0; background: #fff; }
td, th { padding: 6px 10px; height: 32px; }

.hero { display: grid; grid-template-columns: 1.4fr 1fr; gap: 32px; align-items: end; }
.hero img { width: 100%; height: auto; aspect-ratio: 4 / 5; object-fit: cover; border-radius: 10px; }
@media (max-width: 700px) { .hero { grid-template-columns: 1fr; } }
